type Result<T> =
  | { status: 'success'; data: T }
  | { status: 'error'; message: string }

function handle(r: Result<User>) {
  if (r.status === 'success') r.data  // TS knows it's User
}

function isString(val: unknown): val is string {
  return typeof val === 'string'
}

function first<T>(arr: T[]): T | undefined {
  return arr[0]
}
const n = first([1, 2, 3])  // type: number

function getProperty<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key]
}

const palette = {
  red: [255, 0, 0],
  green: '#00ff00',
} satisfies Record<string, string | number[]>

palette.red.map(x => x)  // Still knows it's number[]

import { z } from 'zod'
const UserSchema = z.object({ name: z.string(), age: z.number() })
type User = z.infer<typeof UserSchema>  // { name: string; age: number }
